struct RequireRole: AsyncMiddleware {
    let required: Set<String>
    func respond(to req: Request, chainingTo next: AsyncResponder) async throws -> Response {
        guard let user = req.auth.get(User.self),          // set by an Authenticator
              !required.isDisjoint(with: user.roleNames)   // server-side roles
        else { throw Abort(.forbidden) }                    // deny by default
        return try await next.respond(to: req)
    }
}

let protected = app.grouped(User.guardMiddleware(), RequireRole(required: ["pauser"]))
protected.post("transfers", "pause") { req in HTTPStatus.noContent }
